function pickLogo(){ $('logoin').click(); }
function setLogo(src){
  $('brandLogo').innerHTML=`<button type="button" class="logobtn" onclick="pickLogo()" aria-label="Cambiar el logotipo de tu empresa" title="Clic para subir tu logotipo real (PNG o SVG)"><img class="logoimg" src="${urlImagenSegura(src)}" alt="AL3D"></button><h1 class="t">Cotizador <small>Anuncios Luminosos 3D</small></h1>`;
  /* Un logotipo propio cambia el alto de la fila de la marca, y de ese alto depende
     cuánto se recorre la barra de arriba al desplazarse en el teléfono. */
  ajustarTopbarMovil();
}
/* El logotipo se guardaba tal como venía del archivo. Con una foto de celular de 4 MB en
   base64 no cabía, el setItem fallaba dentro de un catch vacío y el aviso decía «Logotipo
   cargado» igual: se veía en pantalla y desaparecía al recargar. Ahora se reduce a 400 px
   por un canvas antes de guardar, y el aviso dice lo que de verdad pasó.

   Los SVG no pasan por el canvas: son texto, ya pesan poco y rasterizarlos sería perder
   justo lo que los hace buenos para un logotipo. */
const LOGO_MAX_PX=400, LOGO_MAX_BYTES=300000;
function reducirLogo(dataUrl,tipo){
  return new Promise(resolve=>{
    if(/svg/i.test(tipo||'')) return resolve(dataUrl);
    const img=new Image();
    img.onload=()=>{
      try{
        const esc=Math.min(1,LOGO_MAX_PX/Math.max(img.width,img.height));
        if(esc>=1&&dataUrl.length<=LOGO_MAX_BYTES) return resolve(dataUrl);
        const cv=document.createElement('canvas');
        cv.width=Math.max(1,Math.round(img.width*esc));
        cv.height=Math.max(1,Math.round(img.height*esc));
        const cx=cv.getContext('2d');
        cx.drawImage(img,0,0,cv.width,cv.height);
        /* PNG conserva la transparencia, que un logotipo suele necesitar; si sale muy
           pesado —una foto rara vez tiene transparencia útil— se cae a JPEG. */
        let out=cv.toDataURL('image/png');
        if(out.length>LOGO_MAX_BYTES) out=cv.toDataURL('image/jpeg',0.85);
        resolve(out.length<dataUrl.length?out:dataUrl);
      }catch(_){ resolve(dataUrl); }
    };
    img.onerror=()=>resolve(dataUrl);
    img.src=dataUrl;
  });
}
$('logoin').addEventListener('change',e=>{
  const f=e.target.files[0]; if(!f)return;
  const r=new FileReader();
  r.onload=async ev=>{
    const src=await reducirLogo(ev.target.result,f.type);
    setLogo(src);
    if(src.length>LOGO_MAX_BYTES){ toast('El logotipo pesa demasiado para guardarse — se ve ahora, pero no sobrevive a la recarga. Usa un PNG más chico.','err',7000); return; }
    let ok=true; try{localStorage.setItem('al3d_logo',src);}catch(_){ ok=false; }
    if(ok) toast('Logotipo cargado','ok');
    else toast('No se pudo guardar el logotipo: no hay espacio en este dispositivo','err',6000,{label:'Respaldar',fn:()=>respaldar()});
  };
  r.readAsDataURL(f); e.target.value='';
});
function loadLogo(){ let s=null; try{s=localStorage.getItem('al3d_logo');}catch(_){} setLogo(s||AL3D_LOGO); }


/* ===================== Datos de empresa (edita aquí) ===================== */
const EMPRESA = {
  vendedor:  'Elias Guerrero',
  taller:    'Naranjos #648 Col. Lindavista Cp. 45169',
  whatsapp:  '33-2813-0092',
  oficina:   'Naranjos #648 Col. Lindavista Cp. 45169'
};

/* ----- Quién firma esto -----
   El PDF ya resolvió esto: quien autorizó, o el nombre recordado en el dispositivo, y solo si
   no hay ninguno el del código. Pero el mensaje de WhatsApp y el texto que se pega en Canva
   seguían con `EMPRESA.vendedor` a secas, así que la misma cotización salía firmada por dos
   personas distintas según por dónde llegara al cliente: el papel por quien la autorizó y el
   mensaje que lo acompaña por quien está escrito en el archivo. Una definición, tres usos. */
function vendedorActual(){
  return (Q.autorizador||'').trim() || prefGet(PREF_AUTORIZADOR,'') || EMPRESA.vendedor;
}

/* ===================== Enviar la cotización por WhatsApp =====================
   El teléfono del cliente se capturaba al principio de cada cotización y no se usaba
   para nada. Aquí abre su chat con el mensaje ya escrito —folio, proyecto, total
   autorizado y anticipo—, que era lo que se volvía a redactar en cada envío.

   El archivo se sigue adjuntando a mano, y eso no es un descuido: lo que la app llama
   «PDF» es una página HTML que se manda a imprimir, no un archivo, así que no hay nada
   que adjuntar por programa. Adjuntarlo de un toque pide generar un PDF de verdad. */
function telWhatsApp(t){
  const d=String(t||'').replace(/\D/g,'');
  if(!d) return '';
  if(d.length===10) return '52'+d;                 // celular mexicano sin lada de país
  if(d.length===12&&d.startsWith('52')) return d;  // ya viene con 52
  if(d.length===13&&d.startsWith('521')) return d; // formato viejo con el 1
  /* De aquí para abajo no se adivina. Un 11 dígitos que empieza con 1 se lee igual como
     número de Estados Unidos (+1 415 555 2671) que como el formato mexicano viejo sin lada
     de país, así que se manda tal cual: quien escribió «+1» quiso decir +1. Lo que antes
     también pasaba tal cual —un «33» a medias— abría el chat de un número que no era el del
     cliente mientras el aviso decía «WhatsApp abierto»; eso ahora se rechaza y se abre
     WhatsApp sin número, el mismo camino que ya existía para el teléfono vacío. */
  if(d.length>=11&&d.length<=15) return d;         // internacional con lada plausible
  return '';
}
function mensajeWhatsApp(){
  const pf=precioFinal();
  const n=Q.items.filter(it=>it.showInPdf!==false).length;
  const L=[];
  /* Sin nombre en el saludo: la mayoría de los clientes son negocios —«Farmacia San
     Juan», «Tacos El Güero»— y tanto el nombre completo como el primer pedazo se leen
     raro en un «Hola». El nombre ya va en el chat al que se manda. */
  L.push(`Hola, le comparto la cotización *${Q.folio}* de AL3D.`);
  L.push('');
  if((Q.proy||'').trim()) L.push(`*${Q.proy.trim()}*`);
  L.push(`${n} ${n===1?'partida':'partidas'}`);
  L.push(`Total: ${money(pf)}${Q.iva?' (IVA incluido)':' (sin IVA)'}`);
  if(Q.anti>0) L.push(`Anticipo para arrancar: ${money(Q.anti)}`);
  if((Q.entrega||'').trim()) L.push(`Límite de fabricación: ${Q.entrega.trim()}`);
  /* Solo la nota que se escribió a mano. La de respaldo —«El cliente debe proporcionar
     salidas eléctricas»— está redactada para el documento, no para hablarle a alguien;
     en el PDF se sigue imprimiendo igual. */
  const nota=(Q.notaCliente||'').trim();
  if(nota){ L.push(''); L.push(nota); }
  L.push('');
  L.push('Le adjunto el PDF con el desglose. Quedo al pendiente de cualquier duda.');
  L.push(`${vendedorActual()} · AL3D Anuncios Luminosos 3D`);
  return L.join('\n');
}
function enviarPorWhatsApp(){
  const num=telWhatsApp(Q.tel);
  const url='https://wa.me/'+num+'?text='+encodeURIComponent(mensajeWhatsApp());
  /* Sin el 'noopener': window.open lo devuelve null POR ESPECIFICACIÓN cuando se pide, así
     que la app siempre creía que el navegador había bloqueado la ventana y enseñaba el aviso
     de emergencia aunque WhatsApp hubiera abierto bien. Aquí no hace falta: wa.me es un
     destino conocido y la pestaña se abre por acción directa del usuario. */
  const w=window.open(url,'_blank');
  if(!w){ toast('Permite ventanas emergentes para abrir WhatsApp','err',3400); return; }
  /* El hito dice «chat abierto», que es exactamente lo que acaba de pasar: el PDF se
     adjunta a mano y desde aquí no hay manera de saber si se mandó. */
  marcarHito('wa');
  const teniaTel=String(Q.tel||'').replace(/\D/g,'').length>0;
  /* El aviso de éxito se fue: se pintaba en la pestaña que el vendedor acaba de abandonar, así
     que nadie lo leía. Lo que decía —«falta adjuntar el PDF»— ahora vive en el renglón del
     paso, donde se lee ANTES de tocarlo. Los dos avisos de error se quedan: ésos sí dicen que
     algo salió mal, y quien los tiene que leer sigue en esta pestaña porque WhatsApp abrió
     sin chat. */
  if(!num) toast(teniaTel
    ?'El teléfono capturado no parece un número válido — elige el chat en WhatsApp'
    :'Sin teléfono capturado: elige el chat en WhatsApp','err',5200);
}

/* ----- Dejar constancia de que se hizo la propuesta -----
   Este botón se aprieta cuando alguien va a armar el documento que ve el cliente. Ese
   hecho —«a esta cotización ya se le hizo propuesta»— no estaba escrito en ningún lado, y
   es el mismo hueco que tenía «se ganó» hasta hace poco: el dato existe en el momento en
   que alguien toca el botón, y se tiraba.

   Con esto se puede contestar la pregunta que hoy no tiene respuesta: de las que
   presentamos, ¿cuántas se ganaron? Hoy no se sabe, porque no se sabe cuáles se
   presentaron. Y se contesta SIN pedirle a nadie que capture nada y sin cruzar nombres
   contra Canva, que es lo que se rompería: los diseños se llaman como los nombró quien los
   hizo.

   Un registro por folio, con la fecha del primero y del último toque —volver a copiar la
   fila es normal cuando se corrige el documento, y no debería parecer una propuesta nueva—.
   Son unas decenas de bytes por cotización, así que entra al respaldo sin pesar. */
const CANVA_KEY='al3d_canva';
function getPropuestas(){
  try{ const o=JSON.parse(localStorage.getItem(CANVA_KEY)||'{}'); return (o&&typeof o==='object'&&!Array.isArray(o))?o:{}; }
  catch(_){ return {}; }
}
function marcarPropuesta(){
  if(!Q.folio) return;
  try{
    const o=getPropuestas(), ahora=Date.now(), y=o[Q.folio];
    o[Q.folio]=y&&y.primera ? {primera:y.primera,ultima:ahora,veces:(y.veces||1)+1}
                            : {primera:ahora,ultima:ahora,veces:1};
    localStorage.setItem(CANVA_KEY,JSON.stringify(o));
  }catch(_){ /* si no cupo, se pierde la constancia y no pasa nada más: no bloquea el copiado */ }
}

/* ===================== Qué aparato es este =====================
   El contador de folios es local a cada teléfono, así que dos aparatos empiezan en COT-0001 y
   acaban emitiendo el mismo folio para trabajos distintos. Está escrito en los «Pendientes»
   del README y la recomendación es cotizar siempre desde el mismo aparato.

   La plataforma ya resolvió su mitad: `js/datos/prefs.js` tiene un `dispositivo()` que
   guarda cuatro letras en `al3d_pf_disp` —«desambiguar folios, porque dos teléfonos pueden
   emitir COT-0042 el mismo día y sin esto serían el mismo proyecto»— y el cotizador solo la
   LEÍA, una vez, al registrar una venta ganada. Aquí está la misma función, con la misma
   clave, para que los dos lados vean lo mismo.

   Se usa en los dos sitios donde de verdad desempata y en ninguno más: el CSV del historial
   —que es el que se pega en un Sheet donde acaban dos COT-0042 juntos— y la entrada guardada,
   para que esa columna tenga qué decir. El folio que el cliente tiene en la mano no se toca:
   cambiarlo sería cambiar el número de un documento firmado.

   Y NO entra en RESPALDO_KEYS, a propósito y por la misma razón que en la plataforma: es la
   identidad del aparato, no un dato de la empresa. Restaurar un respaldo en un teléfono nuevo
   no puede convertirlo en el viejo. */
const DISP_KEY='al3d_pf_disp';
function dispositivo(){
  let d=prefGet(DISP_KEY,'');
  if(d) return d;
  const AB='23456789ABCDEFGHJKLMNPQRSTUVWXYZ';   // sin 0/O ni 1/I: esto se dicta por teléfono
  try{
    const b=new Uint8Array(4);
    crypto.getRandomValues(b);
    d=Array.from(b,x=>AB[x%AB.length]).join('');
  }catch(_){
    d='D'+String(Date.now()%10000).padStart(4,'0');
  }
  prefSet(DISP_KEY,d);
  return d;
}

/* ===================== Los hitos de la entrega =====================
   Autorizar no es terminar. Después vienen tres cosas que se hacen SIEMPRE y en este orden
   —armar el documento, mandárselo al cliente, registrar la venta— y la app no se acordaba
   de ninguna: el vendedor generaba el PDF, se iba a WhatsApp a adjuntarlo, volvía, y la
   pantalla estaba idéntica a antes de tocar nada. Con cinco llamadas encima, «¿ya mandé
   ésta?» solo se contestaba abriendo la plataforma o el chat.

   Lo más caro era que el dato ya existía y se tiraba. `marcarPropuesta` escribía la
   constancia de que se armó la propuesta en Canva y nadie la leía nunca; `al3d_pf_ganadas`
   solo se leía dentro de `registrarGanada` para no duplicar. Se guardaba el hecho y no se
   enseñaba en ningún sitio.

   Un registro por folio, con la fecha de cada hito. Va en su propia clave y NO dentro de Q,
   por dos razones: `saveState` serializa Q y la pila de deshacer compara justamente esa
   cadena para saber si hubo un cambio, así que un sello de tiempo dentro de Q convertiría
   generar un PDF en un paso para atrás; y los hitos son de la cotización con ese folio, no
   de la que está en pantalla, así que sobreviven a abrirla del historial. Son unas decenas
   de bytes por cotización: entran al respaldo sin pesar.

   El de WhatsApp dice «chat abierto» y no «enviada», y eso no es un matiz: la app abre
   wa.me y el PDF se adjunta a mano, así que saber que se mandó es justo lo que no puede
   saber. Decir «enviada» sería la app afirmando algo que no vio. */
const HITOS_KEY='al3d_hitos';
/* `pista` es lo que hay que saber ANTES de tocar el botón, y va en el renglón del paso que
   toca. Las dos son mudanzas, no texto nuevo: lo que la app llama «PDF» es una página que se
   manda a imprimir, y la única frase que lo explicaba —«usa Compartir → Imprimir / Guardar en
   PDF»— vivía en el aviso de emergencia que solo sale cuando el navegador bloquea la ventana.
   Y el recordatorio de adjuntar el PDF se pintaba DESPUÉS de abrir WhatsApp, o sea en la
   pestaña que el vendedor acaba de abandonar: en el celular wa.me se va a la app y cuando
   vuelve, el aviso ya caducó — y el mensaje le promete al cliente un archivo que nadie
   adjuntó. Puestas aquí se leen a tiempo, en el teléfono y en el escritorio. */
const HITOS=[
  {k:'pdf',  label:'Generar PDF',        hecho:'PDF generado',  pista:'elige «Guardar como PDF»',  fn:'generarPDF()',        cls:'btn-pri', ico:'i-doc'},
  {k:'wa',   label:'Enviar por WhatsApp',hecho:'Chat abierto',  pista:'adjunta el PDF que guardaste', fn:'enviarPorWhatsApp()', cls:'btn-wa',  ico:'i-chat'},
  {k:'venta',label:'Registrar venta',    hecho:'Venta registrada',fn:'abrirRegistrarVenta()',cls:'btn-vta',ico:'i-venta'},
];
function getHitos(){
  try{ const o=JSON.parse(localStorage.getItem(HITOS_KEY)||'{}'); return (o&&typeof o==='object'&&!Array.isArray(o))?o:{}; }
  catch(_){ return {}; }
}
/* Siempre las tres llaves, para que quien lea no tenga que preguntar por la existencia. */
function hitosDe(folio){
  const o=getHitos()[folio||Q.folio]||{};
  return {pdf:o.pdf||0, wa:o.wa||0, venta:o.venta||0};
}
function marcarHito(k){
  if(!Q.folio||!HITOS.some(h=>h.k===k)) return;
  try{
    const o=getHitos();
    const y=(o[Q.folio]&&typeof o[Q.folio]==='object')?o[Q.folio]:{};
    /* La PRIMERA vez manda: reimprimir un PDF en octubre no convierte la entrega de agosto
       en una de octubre. Volver a hacerlo es normal —se corrige el documento, se reabre el
       chat— y no debería parecer un hito nuevo. */
    if(!y[k]) y[k]=Date.now();
    o[Q.folio]=y;
    localStorage.setItem(HITOS_KEY,JSON.stringify(o));
  }catch(_){ /* sin espacio: se pierde la constancia y nada más. No frena la entrega. */ }
  /* El repintado es la mitad del valor, y son TRES los sitios que leen los hitos: el panel
     (renderSummary → renderAuth), la barra de pasos, y el renglón de «qué sigue», que vive en
     updProg. Con los dos primeros el panel decía «✓ PDF generado» y la barra de completitud,
     dos dedos más arriba, seguía ofreciendo «Generar PDF ›». */
  renderSummary(); pintarPasos(); updProg();
}
/* «27 ago» — la fecha corta, que es toda la que hace falta al lado de una palomita. */
function hitoFecha(ts){
  if(!ts) return '';
  try{ return new Date(ts).toLocaleDateString('es-MX',{day:'numeric',month:'short'}); }
  catch(_){ return ''; }
}

/* ===================== Copiar datos para pegar en Canva ===================== */
function copiarParaCanva(){
  const MAT={'al-paint':'Aluminio Blanco/Negro/Pintado','al-brush':'Aluminio Brush Cepillado','acr-vol':'Acrílico + Aluminio (Volumen)','acr-vinil':'Acrílico + Vinil','acero':'Acero Inoxidable'};
  const ACAB={'sencillo':'Sencillo','vinil':'Rotulación de Vinil','sandwich':'Tipo Sándwich con Iluminación'};
  const BAS={'lamina':'Lámina Galvanizada','alucobond':'Alucobond'};
  function descTxt(it){
    let d='';
    if(it.tipo==='letras')    d=`Letras Individuales 3D: Caras en Acrílico, Cantos en ${MAT[it.material]||'Aluminio'}${it.luz?` con Iluminación LED ${it.ilumTipo==='calida'?'Cálida (3000K)':'Fría (6500K)'}`:' sin iluminación'}.`;
    else if(it.tipo==='recorte')  d=`Recorte de Acrílico: ${ACAB[it.acab]||''}.`;
    else if(it.tipo==='bastidor') d=`Bastidor para Letras 3D: estructura tubular de 1" forrada de ${BAS[it.bas]||'lámina galvanizada'}.`;
    else if(it.tipo==='caja'){const tp=cajaTipoPdf(it); d=`Caja de Luz:${tp?' '+tp+',':''} Caras en Acrílico con Iluminación LED Fría.`;}
    if(it.desc) d+=(d?' — ':'')+it.desc;
    return d||'—';
  }
  function medTxt(it){
    if(it.tipo==='letras')  return `${it.altura}cm alt.`;
    if(it.tipo==='recorte') return `${it.altura}cm × pieza`;
    if(it.tipo==='bastidor'||it.tipo==='caja') return `${it.ancho}×${it.alto} cm`;
    return '—';
  }
  function pzasTxt(it){
    if(it.tipo==='letras'||it.tipo==='recorte') return it.n||0;
    if(it.tipo==='bastidor'||it.tipo==='caja')  return 1;
    return it.pz||1;
  }
  /* Mismos criterios que el PDF: solo las partidas visibles, con los precios que
     autorizó el autorizador, para que el texto y el documento no se contradigan. */
  const visibles=Q.items.filter(it=>it.showInPdf!==false);
  const subC=Q.items.reduce((s,it)=>s+itemPrecio(it),0);
  const ivaC=Q.iva?subC*0.16:0;
  const netoC=subC+ivaC;
  const pFinal=precioFinal();
  const ajuste=+(netoC-pFinal).toFixed(2);
  /* El mismo desglose coherente que el PDF: el descuento baja la base y el IVA sale de la
     base descontada, para que los dos documentos digan lo mismo. */
  const hayAjusteC=Math.abs(ajuste)>0.01;
  const dFinC=desgloseFinal();
  const descSinIvaC=+(subC-dFinC.sub).toFixed(2);
  /* Igual que el PDF: las ocultas se cobran, así que se enlistan agrupadas para que las
     líneas sumen el subtotal de abajo. */
  const subOcultoC=+(subC-visibles.reduce((s,it)=>s+itemPrecio(it),0)).toFixed(2);
  const lineas=visibles.map((it,i)=>`${i+1}. ${descTxt(it)}\n   Medidas: ${medTxt(it)}  ·  Pzas: ${pzasTxt(it)}  ·  Total: ${money(itemPrecio(it))}`).join('\n\n')
    +(Math.abs(subOcultoC)>0.01?`\n\n${visibles.length+1}. Conceptos adicionales\n   Total: ${money(subOcultoC)}`:'');
  const txt=`PROYECTO: ${Q.proy||'—'}
CLIENTE: ${Q.cliente||'—'}
DIRECCIÓN: ${direccionPdf()||'—'}
FECHA: ${Q.fecha||'—'}

PARTIDAS:
${lineas}

Subtotal: ${money(subC)}${hayAjusteC&&ajuste>0.01?`\nDescuento: −${money(descSinIvaC)}`:''}${hayAjusteC&&ajuste<-0.01?`\nAjuste: +${money(-descSinIvaC)}`:''}${hayAjusteC?`\nSubtotal ${ajuste>0?'con descuento':'ajustado'}: ${money(dFinC.sub)}`:''}${Q.iva?`\nIVA (16%): ${money(dFinC.iva)}`:''}
${Q.iva?'Total Neto':'Total'}: ${money(dFinC.neto)}${Q.anti>0?`\nAnticipo para arrancar: ${money(Q.anti)}\nResta al entregar: ${money(Math.max(0,dFinC.neto-Q.anti))}`:''}

Nota: ${notaCliente()}
Límite de fabricación: ${Q.entrega||'—'}
Teléfono: ${Q.tel||'—'}
Entre calles: ${Q.entrecalles||'—'}

Vendedor: ${vendedorActual()}
Whatsapp: ${EMPRESA.whatsapp}`;

  copiarTexto(txt,'Datos copiados · listos para pegar en Canva');
  marcarPropuesta();
}

/* ===================== Prompt para imagen de referencia (Gemini) ===================== */
function copiarParaGemini(){
  function descGemini(it){
    const label=it.desc?` "${it.desc}"`:'';
    if(it.tipo==='letras'){
      let fabr='';
      if(it.material==='al-paint') fabr='Fabricadas en Aluminio Pintado';
      else if(it.material==='al-brush') fabr='Fabricadas en Aluminio Brush Cepillado';
      else if(it.material==='acr-vol') fabr='Fabricadas en Acrílico, Cantos en Aluminio';
      else if(it.material==='acr-vinil') fabr='Fabricadas en Acrílico con Rotulación de Vinil, Cantos en Aluminio';
      else if(it.material==='acero') fabr='Fabricadas en Acrílico, Cantos en Acero Inoxidable acabado espejo';
      else fabr='Fabricadas en Aluminio';
      const ilumPos=(it.material==='acr-vol'||it.material==='acr-vinil')?'Interna':'Posterior';
      const ilumColor=(it.ilumTipo==='calida')?'Cálida (3000K)':'Fría (6500K)';
      const ilum=it.luz?`, con Iluminación LED ${ilumPos} ${ilumColor}`:' sin iluminación';
      const alt=it.altura?`, altura de ${it.altura}cm`:'';
      return `Letras Individuales 3D${label} — ${fabr}${alt}${ilum}`;
    }
    if(it.tipo==='recorte'){
      const alt=it.altura?`, ${it.altura}cm de altura`:'';
      if(it.acab==='sandwich') return `Recorte de Acrílico Tipo Sándwich${label} — Con Iluminación LED Fría${alt}`;
      if(it.acab==='vinil')    return `Recorte de Acrílico con Rotulación de Vinil${label}${alt}`;
      return `Recorte de Acrílico Sencillo${label}${alt}`;
    }
    if(it.tipo==='bastidor'){
      const bas=it.bas==='alucobond'?'Alucobond':'Lámina Galvanizada';
      const med=(it.ancho&&it.alto)?`, ${it.ancho}×${it.alto}cm`:'';
      return `Bastidor${label} — Estructura Tubular Forrada de ${bas}${med}`;
    }
    if(it.tipo==='caja'){
      const tipo=cajaTipoPdf(it);
      const med=(it.ancho&&it.alto)?`, ${it.ancho}×${it.alto}cm`:'';
      return `Caja de Luz${tipo?' '+tipo:''}${label} — Cara en Acrílico con Iluminación LED Fría${med}`;
    }
    return null; // partidas manuales no se incluyen en el render visual
  }

  let idx=0;
  const conceptos=Q.items.map(it=>{
    const d=descGemini(it); if(!d) return null;
    return `${++idx}. ${d}`;
  }).filter(Boolean).join('\n');

  const prompt=`Ayudame a crear una imagen tipo render realista del siguiente proyecto:

Proyecto: ${Q.proy||'—'}
Cliente: ${Q.cliente||'—'}

${conceptos||'Sin partidas definidas'}

Importante: respeta todos los elementos, posiciones y acomodo que aparecen en las imágenes de referencia.`;

  copiarTexto(prompt,'Prompt copiado · pégalo en Gemini junto con tu imagen de referencia');
}

/* ===================== Generador de PDF ===================== */
function generarPDF(){
  const itemsForPDF = Q.items.filter(it=>it.showInPdf!==false);
  /* Con todas las partidas ocultas salía un documento con el total completo y cero
     renglones: nada que enseñarle al cliente y un total sin sustento. */
  if(Q.items.length&&!itemsForPDF.length){
    toast('Todas las partidas están ocultas del PDF — muestra al menos una','err',4600); return;
  }
  /* El PDF se arma con los precios ya ajustados por el autorizador, para que las
     filas de la tabla siempre sumen lo que dice el total.

     Las partidas ocultas del PDF siguen cobrándose —lo dice el propio botón: «Ocultar del
     PDF, la partida sigue sumando al total»—, así que su importe no se resta: se imprime
     agrupado en un renglón. Antes el subtotal las incluía pero los renglones no, y el
     cliente recibía una tabla que no sumaba lo que decía abajo. */
  const subVis    = itemsForPDF.reduce((s,it)=>s+itemPrecio(it),0);
  const subOculto = +(Q.items.reduce((s,it)=>s+itemPrecio(it),0)-subVis).toFixed(2);
  const subPdf  = +(subVis+subOculto).toFixed(2);
  const ivaPdf  = Q.iva ? subPdf*0.16 : 0;
  const netoPdf = subPdf+ivaPdf;
  const pFinal  = precioFinal();
  const ajuste  = +(netoPdf-pFinal).toFixed(2); // >0 descuento · <0 aumento
  const hayAjuste = Math.abs(ajuste)>0.01;
  /* El desglose que corresponde a lo que de verdad se cobra. Antes el I.V.A. impreso se
     calculaba sobre el subtotal SIN descuento, así que el documento decía
     «Subtotal 20,000 · I.V.A 3,200 · Descuento 1,200 · Total a pagar 22,000»: cuatro
     números de los que ninguna pareja cuadraba. Ahora el descuento baja la base, el I.V.A.
     sale de la base descontada y el total es exactamente subtotal + I.V.A. */
  const dFin = desgloseFinal();
  const descSinIva = +(subPdf-dFin.sub).toFixed(2);

  /* Etiquetas de catálogos */
  const MAT = {'al-paint':'Aluminio Blanco/Negro/Pintado','al-brush':'Aluminio Brush Cepillado','acr-vol':'Acrílico + Aluminio (Volumen)','acr-vinil':'Acrílico + Vinil','acero':'Acero Inoxidable'};
  const ACAB = {'sencillo':'Sencillo','vinil':'Rotulación de Vinil','sandwich':'Tipo Sándwich con Iluminación'};
  const BAS  = {'lamina':'Lámina Galvanizada','alucobond':'Alucobond'};

  /* El concepto y su especificación en dos renglones y no en uno.
     Antes iba todo seguido —«<b>Letras Individuales 3D:</b> Caras en Acrílico, Cantos en…»—
     y con tres partidas la columna era un párrafo de negritas intercaladas donde había que
     buscar dónde empieza cada cosa. Ahora el nombre del concepto es su propio renglón, en
     negro, y la especificación va debajo en gris: se puede leer solo la columna de conceptos
     de un barrido y bajar al detalle nada más en el que interesa. Las palabras son las mismas.
     Lo único que cambió de texto es la «e» de «estructura tubular», que ahora abre renglón. */
  function desc(it){
    let tit='', esp='';
    if(it.tipo==='letras'){
      tit='Letras Individuales 3D';
      esp=`Caras en Acrílico, Cantos en ${MAT[it.material]||'Aluminio'}${it.luz?` con Iluminación LED ${it.ilumTipo==='calida'?'Cálida (3000K)':'Fría (6500K)'}`:' sin iluminación'}.`;
    }else if(it.tipo==='recorte'){
      tit='Recorte de Acrílico';
      esp=ACAB[it.acab]?`${ACAB[it.acab]}.`:'';   // sin acabado elegido salía «Recorte de Acrílico: .»
    }else if(it.tipo==='bastidor'){
      tit='Bastidor para Letras 3D';
      esp=`Estructura tubular de 1" forrada de ${BAS[it.bas]||'lámina galvanizada'}.`;
    }else if(it.tipo==='caja'){
      tit='Caja de Luz';
      const tp=cajaTipoPdf(it);
      esp=`${tp?tp+', ':''}Caras en Acrílico con Iluminación LED Fría.`;
    }
    const libre = it.desc ? esc(it.desc) : '';
    if(!tit) return libre ? `<span class="cs">${libre}</span>` : '<span class="cs">—</span>';
    return `<span class="cn">${tit}</span>`
      + (esp  ? `<span class="cs">${esp}</span>`  : '')
      + (libre? `<span class="cs">${libre}</span>`: '');
  }
  function med(it){
    if(it.tipo==='letras')  return `${it.altura}cm alt.`;
    if(it.tipo==='recorte') return `${it.altura}cm × pieza`;
    if(it.tipo==='bastidor'||it.tipo==='caja') return `${it.ancho}×${it.alto} cm`;
    return '—';
  }
  function pzas(it){
    if(it.tipo==='letras'||it.tipo==='recorte') return it.n||0;
    if(it.tipo==='bastidor'||it.tipo==='caja')  return 1;
    return it.pz||1;
  }
  /* El unitario tenía dos fallas. La primera: la condición dejaba fuera el tipo
     'manual', que sí trae piezas (pzas() devuelve it.pz y lineTotal multiplica
     it.pz*it.pu), así que una partida manual de 5 piezas a $200 imprimía «Pzas. 5 ·
     Precio unitario $1,000.00 · Total $1,000.00»: el unitario era el total. La
     segunda: money() fija dos decimales, así que un precio ajustado por el
     autorizador a $5,000 entre 3 piezas imprime $1,666.67 y el cliente que
     multiplica obtiene $5,000.01. Cuando la división no cuadra al centavo se marca
     con * y se explica abajo de la tabla; el total de la partida es el que manda. */
  let hayProrrateo=false;
  function pu(it){
    const tot=itemPrecio(it), p=pzas(it);
    if(p>1){
      const u=Math.round(tot/p*100)/100;
      if(Math.abs(u*p-tot)>=0.005){ hayProrrateo=true; return money(u)+' *'; }
      return money(u);
    }
    return money(tot);
  }

  /* ---- La imagen del trabajo ----
     22 de las 25 cotizaciones de Canva que se revisaron llevan, DESPUÉS de la nota, el plano
     cotado del anuncio y una o dos fotos del anuncio instalado. No es adorno: es lo que hace
     que el cliente entienda qué está comprando, y era lo único del documento original que este
     PDF no tenía. La imagen ya la trae la app —es la que leyó la IA, o la que salió del
     escalador con las cotas ya dibujadas encima, que es exactamente lo que pegan en Canva— y
     hasta ahora solo se veía en pantalla.

     Solo imágenes. Si el archivo de referencia es un PDF no se incrusta: un <iframe> dentro de
     la hoja que se manda a imprimir sale en blanco en casi todos los navegadores, y una hoja
     con un recuadro vacío es peor que una hoja sin recuadro. */
  const imgTrabajo = (Q.aiFile && Q.aiFile.type && Q.aiFile.type.indexOf('image/')===0)
    ? urlImagenSegura(Q.aiFile.url) : '';

  /* ---- Reparto de las filas por hoja ----
     El .pg pone min-height:100vh pero ningún techo, y el pie va en position:absolute
     respecto al .pg: al crecer la tabla el bloque se pasaba de la hoja carta y el pie
     se quedaba fuera de la primera página (sin vendedor, sin taller, sin WhatsApp) o,
     en WebKit, las filas de más se recortaban con el overflow:hidden y se perdían.
     Medido con 39 px por fila: con 16 partidas el bloque medía 988 px y todavía cabía;
     con 20 medía 1144 px contra los 1056 de una carta a 96 ppp y Chromium sacaba una
     hoja física de más. Ahora las filas se reparten en varias hojas y cada una lleva su
     encabezado, su thead y su pie.
     Presupuesto de alto medido en layout de impresión (816x1056, media:print): la caja
     útil del .pg son 948 px (1056 menos 28 de padding arriba y 80 abajo), el encabezado
     con la fila de proyecto/dirección ocupa 98 px, el thead 28 px y la tabla 8 px de
     margen, así que al tbody le quedan 814 px; se reparte hasta 790 para dejar dos
     renglones de holgura por si la cuenta de abajo se queda corta. La hoja que además
     cierra con los totales (72 px más 16 de margen) y la nota (22 px más 12) tiene
     692 px; se reparte hasta 640 para que quepa una nota de tres renglones. */
  /* El renglón del cliente son ~30 px más de encabezado en cada hoja, y el bloque de
     totales creció con el anticipo y el subtotal descontado (~54 px en el peor caso).
     Se le quita a lo que se reparte, que es lo que evita que la tabla empuje al pie
     fuera de la hoja. */
  /* La figura se come alto de la última hoja, y hay que quitárselo a lo que se reparte o
     empuja el pie fuera de la carta —que es justo el fallo que este reparto vino a arreglar—.
     Son 312 px: el MÍNIMO que se le reserva. La figura crece por encima de eso cuando la hoja
     le deja hueco —con una sola partida, que es la mediana real, se lleva media hoja— porque
     va en flex:1; lo que no puede es bajar de aquí, que es donde un plano deja de leerse. */
  const ALTO_IMG = imgTrabajo ? 312 : 0;
  /* Medido sobre el diseño nuevo, en la caja útil de 942 px (1 056 menos 30 de padding
     arriba y 84 abajo): el bloque de identidad con sus dos reglas ocupa 67, la ficha de
     datos 75 con la dirección en dos renglones, el encabezado de la tabla 25 y su margen 14.
     A la hoja que cierra hay que quitarle además la fila de cierre —la nota y los totales,
     172 con I.V.A. y plan de pago— y los 312 de plano. A las demás, el renglón que avisa que
     las partidas siguen. */
  const ALTO_TBODY=727, ALTO_TBODY_ULT=588-ALTO_IMG;
  function altoFila(it){
    /* Alto de una fila: 18 px de padding (9 arriba y 9 abajo) más 13 px por renglón.
       Ahora la descripción son bloques —el nombre del concepto y su especificación— y cada
       uno abre su propio renglón, así que se cuentan por separado: el nombre va a 10 px en
       negrita y corta a los 44 caracteres, la especificación a 9.5 px en gris y corta a los
       54, en una columna de 300 px. Se redondea a la alza a propósito: equivocarse de más
       solo gasta papel, equivocarse de menos parte la hoja. */
    const bloques = desc(it).split(/<span class="c[ns]">/).slice(1)
      .map(b=>b.replace(/<[^>]*>/g,'').trim());
    const renglones = bloques.reduce((n,b,i)=>n+Math.max(1,Math.ceil(b.length/(i===0?44:54))),0);
    return 18+Math.max(1,renglones)*13;
  }
  /* Reparte una lista de partidas en hojas.

     Se reparte de ATRÁS HACIA ADELANTE, y eso es lo que cambió al entrar la figura del plano.
     La hoja que cierra es la que menos filas admite —lleva los totales, la nota, el sello o el
     plano—, así que se llena primero ella y las de más arriba van completando las anteriores,
     que sí admiten el alto entero.

     Antes se repartía de adelante hacia atrás y al final se le recortaba el sobrante a la
     última hoja, de un solo tijeretazo. Eso valía mientras el tope de la última fuera 556 px,
     porque de una hoja de 760 nunca sobraban más de 204. Con el plano el tope baja a 244 y
     pueden sobrar más de 500: 14 partidas armaban una última hoja de 1 107 px sobre una carta
     de 1 056, con el pie fuera del papel. Repartiendo desde el final ninguna hoja se llena por
     encima de su propio tope, y da igual cuánto se le reste a la que cierra. */
  function repartir(items,tope,topeUlt){
    const hojas=[]; let hoja=[], alto=0, t=topeUlt;
    for(let i=items.length-1;i>=0;i--){
      const h=altoFila(items[i]);
      if(hoja.length && alto+h>t){ hojas.unshift(hoja); hoja=[]; alto=0; t=tope; }
      hoja.unshift(items[i]); alto+=h;
    }
    hojas.unshift(hoja);
    return hojas;
  }
  const trozos = repartir(itemsForPDF,ALTO_TBODY,ALTO_TBODY_ULT);

  /* ----- Qué hojas se imprimen -----
     Las dos últimas salían siempre, aunque sus campos —los dos opcionales, y los dos
     escondidos dentro de un desplegable— estuvieran vacíos. Una cotización de tres
     renglones se entregaba en cuatro hojas, dos de ellas prácticamente en blanco: una
     con una fecha sola en medio y otra con nada más que el teléfono. Peor: sin límite de
     fabricación, la hoja imprimía una instrucción interna dirigida al vendedor en el
     papel que sustenta un precio. Una hoja que no lleva nada que decir no se imprime. */
  const hayLimite = !!(Q.entrega||'').trim();   // hoja de orden de trabajo
  /* Sin fecha, esa hoja imprimía en gris una instrucción de la app dirigida al vendedor
     —le decía en qué tarjeta capturar el dato, y encima con el nombre que esa tarjeta
     tenía antes del rediseño de dos pantallas— en el papel que sustenta un precio.
     La de instalación, vacía, era una hoja entera con dos recuadros en blanco y sin
     título que dijera qué era. */
  const hayInstal = !!((Q.tel||'').trim()||(Q.entrecalles||'').trim());
  /* El recibo sale cuando hay anticipo pactado, que es el momento en que el dinero se mueve y
     en que hace falta darle un papel al cliente. Sin anticipo sería una hoja de formato en
     blanco pegada a una cotización que todavía nadie aprobó. */
  const hayRecibo = Q.anti > 0;
  /* La orden de trabajo es la misma tabla y se parte igual. Su columna de descripción mide
     58 % y no 40 %, así que altoFila() —calibrada para la estrecha— le sobreestima el alto
     y le caben menos filas de las que caben de verdad. Se deja así: pasarse de largo solo
     gasta una hoja, quedarse corto le corta el pie a la hoja del taller. A la que cierra se
     le restan la nota, el sello y el plano; si no cupiera, el plano se encoge solo.
     El 395 era un literal que no decía de qué estaba hecho, y reservaba el hueco del plano
     TAMBIÉN cuando no hay plano: una orden de trabajo sin imagen se partía en más hojas de las
     que necesita. Ahora el hueco solo se aparta si de verdad hay algo que poner en él. */
  const ALTO_PLANO_OT = imgTrabajo ? 200 : 0;
  const trozosOT = hayLimite ? repartir(Q.items,727,595-ALTO_PLANO_OT) : [];

  /* ----- Por qué la hoja del límite se volvió una orden de trabajo -----
     Antes era una hoja con la fecha sola dentro de un recuadro en medio del papel. Esa hoja no
     existe en la realidad: de las 25 cotizaciones de Canva que se revisaron, 18 la traen y las
     18 salen EN BLANCO, con los placeholders de la plantilla puestos («6 ago 2025»,
     «MIERCOLES 05 DE MARZO»). Lo que sí existe —en 7 de las 25— es una copia de la cotización
     con las dos columnas de precio borradas, el límite estampado en verde y rojo, y el plano.
     Es la hoja del taller, y el taller no tiene que ver el precio.

     Esa hoja se arma con Q.items y no con itemsForPDF a propósito: «ocultar del PDF» esconde
     una partida de los ojos del cliente, no de los de quien la tiene que fabricar. Y aquí no
     hay precio que esconder, que era la única razón de ocultarla.

     ----- Y por qué el recibo no lleva encabezado -----
     El recibo de Canva (Adila Spa, hoja 3) es una hoja limpia: sin logo arriba, sin cintillos
     de folio y fecha, y sin la cinta azul. Tiene sentido y no es descuido: es un formato para
     escribir encima y para cortar por la mitad, y la cinta se transparentaba justo por el
     hueco vacío del campo «Fecha». Lo único que se le deja es el pie, por el número de hoja:
     un juego de hojas que se desordena sobre un escritorio no se vuelve a armar. */
  const TOTAL_HOJAS = trozos.length + 1 + trozosOT.length + (hayInstal?1:0) + (hayRecibo?1:0);
  const HOJA_TERMINOS = trozos.length + 1;
  const HOJA_TRABAJO  = HOJA_TERMINOS + 1;
  const HOJA_INSTAL   = HOJA_TRABAJO + trozosOT.length;
  const HOJA_RECIBO   = HOJA_INSTAL + (hayInstal?1:0);

  /* La cebra lleva índice global: si se reiniciara en cada hoja, dos filas seguidas
     saldrían del mismo color al cambiar de página. */
  let idxFila=0;
  const filaHTML = it=>`
      <tr class="${idxFila++%2===0?'re':'ro'}">
        <td>${desc(it)}</td>
        <td class="c">${med(it)}</td>
        <td class="c">${pzas(it)}</td>
        <td class="r num">${pu(it)}</td>
        <td class="r num tot">${money(itemPrecio(it))}</td>
      </tr>`;

  /* Logo */
  /* El logotipo del documento.

     Antes esto era un ternario con una rama muerta: `logoSrc` salía de una constante que nunca
     era vacía, así que el `else` —nueve líneas de SVG dibujadas a mano, con un TERCER juego de
     azules que no eran los del logotipo— no se pintaba jamás.

     Y el <img> se repetía tal cual en cada sitio donde hace falta: una vez por hoja en el
     encabezado y DOS veces en cada recibo, con el dibujo entero metido en cada copia. Con el
     logotipo en vector eso serían 64 KB por aparición. Ahora el dibujo entra UNA vez en el
     documento, dentro de un <symbol>, y cada sitio pone un <use> de 40 caracteres. Es el mismo
     recurso que las dos apps ya usan para sus 31 iconos.

     El logotipo que sube el usuario sigue ganando, y ése sí va como <img>: es un archivo suyo,
     no la marca de AL3D. */
  const logoPropio = (()=>{ try{ return localStorage.getItem('al3d_logo')||''; }catch(_){ return ''; } })();
  const marcaDef = logoPropio ? '' : `<svg width="0" height="0" style="position:absolute" aria-hidden="true"><defs>
      <symbol id="marca-al3d" viewBox="0 0 3120 1560">${MARCA_SVG.replace(/^<svg[^>]*>/,'').replace(/<\/svg>$/,'')}</symbol>
    </defs></svg>`;
  const logoH = logoPropio
    ? `<img src="${urlImagenSegura(logoPropio)}" alt="AL3D" style="height:38px;max-width:180px;object-fit:contain;display:block">`
    : `<svg class="marca" viewBox="0 0 3120 1560" role="img" aria-label="AL3D"><use href="#marca-al3d"/></svg>`;

  /* Marca de esquina. Antes eran dos trazos que arrancaban en el borde y morían a media
     hoja, y le pasaban por encima a la fecha y al final de la dirección. Ahora vive dentro
     de la banda del encabezado, entra por la esquina y se hunde debajo de la regla azul:
     ocupa el hueco que dejó el logotipo y no se cruza con ningún texto, porque el bloque
     de identidad del documento se movió todo a la izquierda. */
  const deco=`<svg class="deco" width="218" height="80" viewBox="0 0 218 80" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
    <defs>
      <linearGradient id="decoGrad" x1="100%" y1="0%" x2="12%" y2="100%">
        <stop offset="0%" stop-color="#1b2470"/>
        <stop offset="52%" stop-color="var(--brand)"/>
        <stop offset="100%" stop-color="#a9b5ff"/>
      </linearGradient>
    </defs>
    <path d="M238,-16 C162,-10 112,16 92,58 C87,70 85,77 85,88" stroke="url(#decoGrad)" stroke-width="30" fill="none" stroke-linecap="butt"/>
    <path d="M238,20 C188,25 156,41 143,70 C141,77 140,82 140,88" stroke="#c9d2fb" stroke-width="8" fill="none" stroke-linecap="butt" opacity=".9"/>
  </svg>`;

  /* Encabezado.
     El folio va aquí, en todas las hojas. No estaba en ninguna: se escribía una sola vez en
     el <title>, que no se imprime. Es el identificador de toda la app —nombra la entrada del
     historial, encabeza el mensaje de WhatsApp, es la primera columna del CSV y tiene su
     propio contador— y el papel que sustenta un precio salía sin él, así que un cliente con
     dos cotizaciones de la misma semana no podía decir cuál autoriza.

     Antes el folio y la fecha eran dos píldoras azules pegadas a la derecha y el tipo de
     documento se anunciaba con un título centrado más abajo, en las hojas que lo tenían: dos
     lugares distintos para decir qué es esta hoja. Ahora es un solo bloque de identidad
     —logotipo, tipo de documento, folio y fecha— alineado a la izquierda, y las hojas ya no
     llevan título suelto. Eso además libera la esquina derecha para la marca. */
  function hdr(titulo,fecha){
    const meta=[Q.folio?`<b>${esc(Q.folio)}</b>`:'',fecha?esc(fecha):''].filter(Boolean).join(' &nbsp;·&nbsp; ');
    return `<div class="mh">
      <div class="mh-logo">${logoH}</div>
      <div class="mh-bar"></div>
      <div>
        <div class="mh-t">${titulo}</div>
        ${meta?`<div class="mh-m">${meta}</div>`:''}
      </div>
    </div>
    <div class="rule"></div><div class="rule2"></div>`;
  }

  /* Ficha de datos del proyecto.
     Eran tres barras con etiqueta azul y relleno lavanda que ocupaban tres renglones enteros
     y hacían que el documento pareciera un formulario por llenar. Ahora es una tarjeta con
     acento azul a la izquierda y las etiquetas en versalitas encima de su valor: cabe en un
     renglón, se lee de un barrido y el azul de la marca sigue puesto donde se ve.

     El nombre del cliente no aparecía en ninguna hoja del PDF, aunque es obligatorio para
     autorizar: la cotización llegaba sin decir de quién era. Y sin dirección capturada, la
     celda salía rotulada y vacía —un campo con nombre y nada dentro— en las tres hojas que
     reutilizan esta ficha: si no hay dato no hay celda, y las otras dos toman el ancho. */
  function fichaDatos(){
    const celda=(etq,val)=>`<div class="dato"><span class="lbl">${etq}</span><span class="val">${val}</span></div>`;
    const dirPdf=esc(direccionPdf()).trim();
    return `<div class="datos">
      ${celda('Cliente',esc(Q.cliente)||'&mdash;')}
      ${celda('Proyecto',esc(Q.proy)||'&mdash;')}
      ${dirPdf?celda('Dirección',dirPdf):''}
    </div>`;
  }

  /* Pie, con el número de hoja: un juego de hojas que se desordena sobre un escritorio no se
     volvía a armar. La barra azul se fue al borde mismo del papel, a sangre, en vez de flotar
     redondeada a 26 px del canto. */
  function footer(cols,hoja){
    const colsHTML = cols.map(c=>`<div class="pie-c"><span class="lbl">${c.label}</span><span>${c.val}</span></div>`).join('');
    return `<div class="pie">
      <div class="pie-hr"></div>
      <div class="pie-cols">${colsHTML}</div>
      ${hoja?`<div class="pie-h">Hoja ${hoja} de ${TOTAL_HOJAS} &nbsp;·&nbsp; ${esc(Q.folio)}</div>`:''}
    </div>
    <div class="barra"></div>`;
  }

  const vendedorPdf = vendedorActual();
  const footerCot = hoja => footer([
    {label:'Vendedor',val:esc(vendedorPdf)},
    {label:'Dirección del taller',val:esc(EMPRESA.taller)},
    {label:'WhatsApp',val:esc(EMPRESA.whatsapp)}
  ],hoja);

  /* La figura del plano, con su rótulo. Antes era una imagen suelta centrada debajo de la
     nota, con media hoja en blanco por debajo: la partida más común es una sola —14 de las 25
     cotizaciones que se revisaron traen una— así que la hoja quedaba con un tercio de tinta
     arriba y dos tercios de nada. Ahora la figura CRECE hasta ocupar el hueco que le quede a
     la hoja, con la imagen centrada y sin deformarse. La composición se cierra sola. */
  const figura = () => imgTrabajo
    ? `<div class="fig">
      <span class="lbl">Plano y referencia del proyecto</span>
      <div class="fig-box"><img src="${imgTrabajo}" alt="Plano del anuncio cotizado"></div>
    </div>`
    : '';

  /* Los ocho apartados de términos, como datos y no como ocho bloques de HTML repetido.
     El texto es el mismo, carácter por carácter, que el que se venía imprimiendo: solo salió
     del marcado para que los ocho se pinten con la misma plantilla y no haya un apartado con
     el margen de otro. Las etiquetas <u> son literales del documento, no dato de nadie. */
  const TERMINOS = [
    ['Pagos y Facturación',['50% de anticipo para comenzar fabricación.','50% al finalizar, debe liquidar en máximo 2 días posterior a la instalación.','<u>Excepción: proyectos mayores a $60,000 MXN.</u>','Si requiere factura, el anticipo es más IVA.','La cotización es válida por 10 días.']],
    ['Requisitos para Instalación',['En caso de que el proyecto lleve iluminación, el cliente debe proporcionar salida eléctrica detrás de donde se instalará el anuncio.','Área limpia, accesible y segura.','El cliente debe gestionar accesos, permisos y condiciones necesarias.','Cualquier retraso por falta de esto será responsabilidad del cliente.']],
    ['Modificaciones',['Cambios al diseño aprobado pueden generar costos y retrasos.','Deben ser autorizados previamente.','AL3D no responde por fallas si el cliente exige cambios fuera de especificación.']],
    ['Garantías',['1 año en material eléctrico.','2 años en colorimetría.','Se atiende según disponibilidad del equipo.','No aplica si fue instalado/modificado por terceros o expuesto a condiciones extremas.']],
    ['Cancelaciones y Penalizaciones',['El anticipo no es reembolsable.','Si se cancela con el proyecto iniciado o materiales comprados, se debe pagar el 100%.','Después de 10 días sin pago, AL3D puede retirar el anuncio.']],
    ['Uso y Responsabilidad',['Uso indebido o manipulación externa a nosotros.','Clima extremo.','Fallas estructurales del inmueble.'],'AL3D no se hace responsable por:'],
    ['Permisos',['El cliente debe tramitar los permisos.','AL3D no se hace responsable por multas o clausuras.']],
    ['Consentimiento y Uso de Imágenes',['<u>El depósito implica aceptación de todos estos términos.</u>','El cliente autoriza a AL3D a usar imágenes del proyecto con fines promocionales y de portafolio.']],
  ];
  const tsec = (n,[titulo,puntos,intro]) => `<div class="tsec">
      <div class="tsec-h"><div class="tsec-n">${n}</div><div class="tsec-t">${titulo}</div></div>
      ${intro?`<p>${intro}</p>`:''}
      <ul>${puntos.map(p=>`<li>${p}</li>`).join('')}</ul>
    </div>`;

  const html = `<!DOCTYPE html>
<html lang="es"><head><meta charset="UTF-8">
<title>Cotización ${esc(Q.folio)} · AL3D</title>
<!-- Inter, sin bloquear, igual que en las dos apps. Sin señal no llega y el documento cae a la
     misma reserva que la app: las dos superficies siguen coincidiendo, que es lo que se pedía. -->
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet" media="print" onload="this.media='all';this.onload=null">
<style>
*{box-sizing:border-box;margin:0;padding:0}
/* Una escala, no veinte tamaños sueltos. El documento entero se apoya en estos valores:
   7 px para versalitas de etiqueta, 9 px para lo secundario, 9.5 px para el cuerpo de tabla,
   10 px para el nombre de un concepto, 14 px para el total y 17 px para el tipo de documento.
   Y una rampa de grises de tres pasos —tinta, secundario, terciario— en vez de un gris por
   ocasión: lo que se lee siempre a #171a2b, lo que acompaña a #5a6076 y los rótulos a #8a90a6.
   Medido sobre blanco: 14.6:1, 6.4:1 y 3.4:1. El terciario solo rotula, nunca informa. */
:root{
  /* Lo declara la app (index.html:42) y el documento no lo hacía, siendo la superficie que más
     lo necesita: con el tema oscuro automático de Chrome en Android, la cotización que se manda
     al cliente se invertía A MEDIAS —las tarjetas y los grises sí, los degradados de marca no—. */
  color-scheme:only light;
  --ink:#171a2b; --ink2:#5a6076; --ink3:#8a90a6;
  /* El azul del papel era un CUARTO azul: ni --a (#4060f8) ni --a-fuerte (#3018f8), sino un
     #3a4ad8 que no está en ningún token. El cliente veía en el papel un azul distinto del que
     hay en la pantalla y del que tiene el logotipo 13 px más allá, en el mismo encabezado.
     Se elige --a-fuerte y no --a porque en este documento TODO lo que lleva blanco encima es
     letra chica —th a 7.5 px, .neto a 8, .tsec-n a 9.5, .rec-badge a 6.5— y sobre blanco --a da
     4.95:1 mientras --a-fuerte da 8.04:1. Es la regla de contraste que el propio sistema ya
     escribió. --brandd era un tercer azul del documento y no lo justifica nada. */
  --brand:#3018f8; --brandd:#3018f8; --brandl:#eef1fd;
  --line:#dfe3f0; --line2:#c4cae0; --wash:#f7f8fd;
}
/* La MISMA cadena de tipografía que la app, carácter por carácter. El documento era la única
   superficie del producto puesta en otra letra: la app en Inter y lo que ve el cliente en Segoe
   UI. Y la reserva es la misma, así que sin señal las dos caen al mismo tipo — que es lo que
   importa: con red o sin ella, las dos coinciden. */
body{font-family:'Inter','Segoe UI',Roboto,Helvetica,Arial,'Apple Color Emoji','Segoe UI Emoji','Noto Color Emoji','Apple Symbols','Segoe UI Symbol','Noto Sans Symbols 2',sans-serif;color:var(--ink);font-size:10px;background:#fff;-webkit-font-smoothing:antialiased}
.pg{page-break-after:always;padding:30px 34px 84px;min-height:100vh;position:relative;overflow:hidden;display:flex;flex-direction:column}
.pg:last-child{page-break-after:auto}
/* La marca de esquina está posicionada, así que se pintaba ENCIMA del contenido y tapaba la
   fecha y el final de la dirección. Va al fondo; el contenido, arriba. El pie y la barra son
   la excepción: van posicionados a propósito y necesitan una regla más específica, porque el
   selector de arriba les ganaba y les devolvía position:relative. */
.pg>svg.deco{position:absolute;top:0;right:0;z-index:0;pointer-events:none}
.pg>*:not(svg){position:relative;z-index:1}
.pg>.pie,.pg>.barra{position:absolute}

/* Bloque de identidad del documento */
.mh{display:flex;align-items:flex-start;gap:13px;margin-bottom:10px}
.mh-logo{flex:0 0 auto;padding-top:1px}
/* El logotipo en papel. Mismas medidas que tenía como <img>: 38 px de alto y hasta 180 de
   ancho. Va como <svg><use> y no como imagen porque el dibujo entra una sola vez por
   documento; a 64 KB la copia, repetirlo en cada hoja y dos veces por recibo se notaba. */
.marca{height:38px;width:auto;max-width:180px;display:block}
.mh-bar{width:1.5px;align-self:stretch;background:var(--line2)}
.mh-t{font-size:17px;font-weight:800;color:var(--brandd);letter-spacing:.13em;line-height:1.08;text-transform:uppercase}
.mh-m{font-size:9px;color:var(--ink2);letter-spacing:.05em;margin-top:4px}
.mh-m b{color:var(--ink);font-weight:700}
.rule{height:2.5px;background:var(--brand)}
.rule2{height:1px;background:var(--line);margin-bottom:14px}

/* Ficha de datos */
.datos{display:flex;border:1px solid var(--line);border-left:3px solid var(--brand);border-radius:6px;background:var(--wash);margin-bottom:14px;overflow:hidden}
.dato{flex:1;padding:9px 12px;min-width:0}
.dato+.dato{border-left:1px solid var(--line)}
.lbl{display:block;font-size:7px;font-weight:700;letter-spacing:.11em;text-transform:uppercase;color:var(--brand)}
.val{display:block;font-size:10.5px;font-weight:600;color:var(--ink);line-height:1.35;margin-top:3px}

/* Tabla de partidas */
table{width:100%;border-collapse:collapse;margin-bottom:14px}
thead{display:table-header-group}
th{background:var(--brand);color:#fff;font-size:7.5px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;padding:8px 10px;text-align:left}
td{padding:9px 10px;font-size:9.5px;border-bottom:1px solid var(--line);vertical-align:top;line-height:1.37}
th.c,td.c{text-align:center} th.r,td.r{text-align:right}
/* La alternancia re/ro existía desde siempre pero las dos clases pintaban el mismo #fff, o
   sea que no pintaba nada. Ahora sí alterna, con un tinte apenas perceptible: con la columna
   de conceptos en dos alturas, el tinte es para seguir el renglón, no para gritar. El fondo
   sale impreso porque el @media print de abajo trae print-color-adjust:exact. */
.re td{background:#fff}
.ro td{background:var(--wash)}
tbody tr{page-break-inside:avoid}
.cn{display:block;font-size:10px;font-weight:700;color:var(--ink);line-height:1.3}
.cs{display:block;font-size:9.5px;color:var(--ink2);line-height:1.37;margin-top:2px}
td.c{color:var(--ink2)}
/* Cifras de ancho fijo. Sin esto el 1 mide menos que el 8 y una columna de importes
   alineada a la derecha queda con los puntos decimales bailando. */
.num{font-variant-numeric:tabular-nums;font-feature-settings:"tnum";white-space:nowrap}
.tot{font-weight:700;color:var(--ink)}

/* Cierre de la cotización · la nota a la izquierda y los totales a la derecha.
   Iban uno debajo del otro y dejaban vacío medio ancho de hoja al lado de los totales
   —470 px por 160— mientras la nota, que es el campo que más trabaja del documento, se
   apretaba abajo en un renglón centrado. Compartiendo el renglón se llena el hueco y le
   quedan 70 px más de alto al plano. */
.cierre{display:flex;align-items:stretch;gap:16px;margin-bottom:14px}
.tot-card{flex:0 0 288px;border:1px solid var(--line);border-radius:8px;overflow:hidden;align-self:flex-start}
.trow{display:flex;justify-content:space-between;align-items:baseline;padding:6px 13px;font-size:9.5px}
.trow>span:first-child{color:var(--ink2)}
.trow>span:last-child{font-variant-numeric:tabular-nums;font-feature-settings:"tnum";font-weight:600;white-space:nowrap}
.trow-ok{background:#eaf7f0} .trow-ok>span{color:#0a6b3f!important;font-weight:700}
.trow-av{background:#fdf4e3} .trow-av>span{color:#8a5c0a!important;font-weight:700}
.trow-iva{background:var(--brandl)}
.neto{display:flex;justify-content:space-between;align-items:center;background:var(--brand);color:#fff;padding:10px 13px}
.neto>span:first-child{font-size:8px;font-weight:700;letter-spacing:.12em;text-transform:uppercase}
.neto>span:last-child{font-size:15px;font-weight:800;font-variant-numeric:tabular-nums;font-feature-settings:"tnum";white-space:nowrap}
/* El plan de pago iba como dos renglones más de la misma lista, con el mismo peso que el
   subtotal: el cliente leía cinco cifras seguidas sin saber cuáles suman y cuáles se pagan.
   Va aparte, después del total, con su propio rótulo. */
.pago{border-top:1px solid var(--line);background:var(--wash);padding:8px 13px 9px}
.pago>.lbl{color:var(--ink3);margin-bottom:4px}

/* Nota */
/* La nota crece solo cuando comparte renglón con los totales. Suelta en una hoja —la del
   taller, la de instalación— el .pg es una columna flex y un flex:1 la estiraba a 240 px con
   un renglón de texto flotando en medio. */
.nota{flex:0 0 auto;min-width:0;border-left:3px solid var(--brand);background:var(--brandl);border-radius:0 6px 6px 0;padding:10px 14px;margin-bottom:14px}
.cierre>.nota{flex:1 1 auto;margin-bottom:0;display:flex;flex-direction:column;justify-content:center}
.nota>.lbl{color:var(--brandd);margin-bottom:4px}
.nota p{font-size:9.5px;line-height:1.5;color:var(--ink)}
.nota small{display:block;font-size:8px;color:var(--ink2);margin-top:5px}

/* Figura del plano · crece hasta llenar el hueco que le quede a la hoja */
.fig{flex:1 1 auto;min-height:0;display:flex;flex-direction:column;margin-bottom:4px}
.fig>.lbl{color:var(--ink3);margin-bottom:5px}
/* Fondo blanco y con techo. Con fondo gris y sin techo, un plano ancho dentro de una caja
   de 600 px de alto dejaba dos bandas grises arriba y abajo de la imagen: la caja se leía
   como un hueco por llenar en vez de como un marco. Blanca es un marco, y a 430 px el plano
   ya se ve a tamaño de trabajo sin comerse la hoja entera. */
.fig-box{flex:1 1 auto;min-height:0;max-height:430px;display:flex;align-items:center;justify-content:center;border:1px solid var(--line);border-radius:8px;background:#fff;padding:9px}
.fig-box img{max-width:100%;max-height:100%;object-fit:contain;border-radius:4px}
.sigue{text-align:center;font-size:9px;color:var(--ink3);letter-spacing:.03em;margin-bottom:12px}

/* Pie */
.pie{bottom:26px;left:34px;right:34px;z-index:1}
.pie-hr{height:1px;background:var(--line);margin-bottom:10px}
.pie-cols{display:flex;gap:18px}
.pie-c{flex:1;text-align:center}
.pie-c>.lbl{color:var(--ink3)}
.pie-c>span{display:block;font-size:9px;color:var(--ink);font-weight:600;margin-top:2px}
.pie-h{text-align:center;font-size:8px;color:var(--ink3);letter-spacing:.07em;margin-top:9px}
.barra{left:0;right:0;bottom:0;height:7px;background:var(--brand)}

/* Términos y condiciones */
/* Las dos columnas se estiran a lo alto de la hoja y sus apartados se reparten el hueco,
   así que las dos acaban a ras del bloque de aceptación en vez de dejar 250 px de papel en
   blanco en medio del documento que más importa leer. */
.tt{display:grid;grid-template-columns:1fr 1px 1fr;gap:0 26px;margin-top:2px;flex:1 1 auto;min-height:0;margin-bottom:16px}
.tt-col{align-content:start}
.tt-div{background:var(--line)}
/* Los términos estaban a 8.8 px. Es letra de contrato en papel: la parte del documento
   que más importa leer bien era la más chica de todas, y encima dejaba media hoja en
   blanco. A 9.8 px con interlínea de 1.68 se leen y la hoja se llena. */
.tsec{margin-bottom:26px}
.tsec:last-child{margin-bottom:0}
.tsec-h{display:flex;align-items:center;gap:8px;margin-bottom:6px}
.tsec-n{flex:0 0 auto;width:17px;height:17px;border-radius:4px;background:var(--brand);color:#fff;font-size:9.5px;font-weight:800;display:flex;align-items:center;justify-content:center}
.tsec-t{font-size:11px;font-weight:700;color:var(--brandd)}
.tsec ul{padding-left:25px;list-style-position:outside;font-size:10.4px;line-height:1.7;color:var(--ink2)}
.tsec li{margin-bottom:4px;padding-left:2px}
.tsec>p{font-size:10.4px;line-height:1.7;color:var(--ink2);padding-left:25px;margin-bottom:5px}
.tsec u{color:var(--ink);font-weight:600}

/* Aceptación. El apartado 8 dice que el depósito implica la aceptación de todos estos
   términos, así que la firma no hace falta: se ofrece para quien la quiera. Va al pie de
   la hoja de términos porque es donde acaba lo que se acepta, y porque ahí quedaban 300 px
   de papel en blanco al final del documento más importante del paquete. */
.acepta{flex:0 0 auto;border:1px solid var(--line);border-top:3px solid var(--brand);border-radius:0 0 8px 8px;background:var(--wash);padding:13px 16px 14px}
.acepta>.lbl{color:var(--brandd)}
.acepta p{font-size:9.5px;line-height:1.55;color:var(--ink2);margin:5px 0 34px;max-width:640px}
.acepta-f{display:flex;gap:30px}
.acepta-f>div{flex:1;border-top:1px solid var(--ink);padding-top:4px;font-size:8.5px;color:var(--ink2)}
.acepta-f>div:last-child{flex:0 0 160px}
.acepta-m{font-size:8.5px;color:var(--ink3);margin-top:12px;letter-spacing:.03em}

/* Sello del límite de fabricación · el verde y el rojo son los del taller, no un capricho */
.sello{display:flex;justify-content:center;margin-bottom:15px}
.sello-in{border:1.5px solid #8fd3a2;background:#eef9f1;border-radius:9px;padding:11px 30px;text-align:center}
.sello-in>.lbl{color:#1c6b3c}
.sello-f{font-size:16px;font-weight:800;color:#c62828;letter-spacing:.05em;line-height:1.15;margin-top:5px}

/* Recibo de pago */
.rec{display:flex;flex:1 1 auto;min-height:420px;border:1px solid var(--line);border-radius:9px;overflow:hidden}
.rec-tal{width:22%;background:var(--wash);border-right:1.5px dashed var(--line2);padding:13px 12px;display:flex;flex-direction:column}
/* Los renglones se reparten en el alto del recibo en vez de amontonarse arriba con un
   vacío de 150 px debajo. Un formato que se llena a mano quiere renglones separados. */
.rec-campos{flex:1 1 auto;display:flex;flex-direction:column;justify-content:space-evenly;padding:4px 0}
.rec-campos>*{margin-bottom:0}
.rec-tal-campos{flex:1 1 auto;display:flex;flex-direction:column;justify-content:space-evenly}
.rec-tal-campos>.rec-f{margin-bottom:0}
.rec-logo{flex:0 0 auto}
.rec-badge{display:inline-block;align-self:flex-start;background:var(--brand);color:#fff;font-size:6.5px;font-weight:700;letter-spacing:.09em;text-transform:uppercase;padding:3px 7px;border-radius:3px;margin:9px 0 13px}
.rec-f{margin-bottom:11px}
.rec-f>.lbl{color:var(--ink3);margin-bottom:3px}
.rec-l{border-bottom:1px solid var(--ink);min-height:15px;font-size:9px;font-weight:600;overflow:hidden;white-space:nowrap}
.rec-tal>.pie-h{margin-top:auto;text-align:left;letter-spacing:.03em}
.rec-b{flex:1;padding:13px 15px;display:flex;flex-direction:column;min-width:0}
.rec-h{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:9px}
.rec-t{font-size:13px;font-weight:800;color:var(--ink);letter-spacing:.01em}
.rec-fecha{display:flex;align-items:stretch;border:1.5px solid var(--brand);border-radius:6px;overflow:hidden;flex:0 0 auto}
.rec-fecha>b{background:var(--brand);color:#fff;font-size:7.5px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;padding:6px 10px}
.rec-fecha>i{background:#fff;width:106px}
.cas{display:inline-flex;align-items:center;gap:5px;font-size:9px;color:var(--ink);margin-right:15px}
.cas>b{width:9px;height:9px;border:1.2px solid var(--ink);border-radius:2px;flex:0 0 auto}
.rline{display:flex;align-items:baseline;gap:7px;margin-bottom:10px;font-size:9px}
.rline>b{font-weight:700;white-space:nowrap;color:var(--ink)}
.rline>span{flex:1;border-bottom:1px solid var(--ink);min-height:15px;font-size:9px;font-weight:600;padding:0 4px;overflow:hidden;white-space:nowrap}
.rfirmas{display:flex;gap:26px;margin-top:auto;padding-top:16px}
.rfirma{flex:1;text-align:center;border-top:1px solid var(--ink);padding-top:4px;font-size:8px;color:var(--ink2)}
.rpie{text-align:center;font-size:7.5px;color:var(--ink3);margin-top:9px}
.rcut{height:1px;border-top:1.5px dashed var(--line2);margin:15px 0;flex:0 0 auto}

/* La barra del visor. Nace APAGADA y solo la enciende el @media screen de aquí abajo: así no
   depende de que el «display:none» de un @media print llegue a tiempo, que es la clase de cosa
   que sale mal en una impresora y no en la pantalla donde se probó. */
.visor{display:none}
:root{--visor-alto:0px}

/* ----- La hoja, en pantalla -----
   Este documento se abre en una pestaña nueva y hasta ahora ahí no era una hoja: era una cinta
   blanca del ancho del navegador. «.pg» no tenía «width» —solo padding— y su «min-height:100vh»
   es el alto de la VENTANA, así que cada «hoja» medía lo que midiera el navegador. Medido en
   Chromium: 1440×900 en pantalla y 816×1056 al imprimir. Toda la maqueta está calculada para lo
   segundo y no se podía ver hasta que ya estaba en el diálogo de imprimir.

   Y el pie lo delataba: va en position:absolute contra el «.pg», así que en pantalla flotaba al
   fondo de un bloque de alto-ventana, a cientos de píxeles de donde iba a salir en el papel.

   Esto le da a la pantalla la geometría que el papel ya tenía. Va DESPUÉS de «.pg» en el archivo
   —las dos reglas pesan igual y gana la última— e INMEDIATAMENTE ANTES del @media print, que no
   se toca ni un carácter: un medio 'print' no puede casar con 'screen', así que lo de aquí no
   existe cuando se imprime y la salida en papel es exactamente la de antes. */
@media screen{
  :root{--visor-alto:54px}
  .visor{display:flex;align-items:center;gap:12px;position:fixed;top:0;left:0;right:0;height:54px;
    padding:0 18px;background:#fff;border-bottom:1px solid var(--line);z-index:9;
    box-shadow:0 1px 6px rgba(20,22,43,.06)}
  .visor-t{font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--ink3)}
  .visor-h{font-size:11px;color:var(--ink2);margin-left:auto}
  .visor-b{font:inherit;font-size:12px;font-weight:700;border:0;border-radius:6px;padding:9px 16px;
    background:var(--brand);color:#fff;cursor:pointer}
  .visor-b:hover{background:var(--brandd)}
  html{background:#e9eaf0}
  body{background:transparent;padding:calc(var(--visor-alto) + 22px) 16px 44px}
  /* 816×1056 son 8.5×11 pulgadas a 96 ppp. «height» y no «min-height»: una hoja de papel no
     crece, y si el contenido no cupiera hay que verlo aquí y no descubrirlo en la impresora. */
  .pg{width:816px;height:1056px;min-height:0;margin:0 auto 22px;background:#fff;
      box-shadow:0 1px 3px rgba(20,22,43,.10),0 10px 28px rgba(20,22,43,.16)}
  .pg:last-child{margin-bottom:0}
}
/* En un teléfono, 816 px no caben en 430. La hoja se encoge entera en vez de salirse a lo ancho,
   que es justo la queja de la que sale todo esto. «zoom» y no «transform:scale»: scale no encoge
   la caja de maqueta, así que la página seguiría desbordando por debajo del dibujo. */
@media screen and (max-width:880px){
  body{padding:calc(var(--visor-alto) + 12px) 0 28px}
  .pg{zoom:.52}
}
@media print{@page{margin:0;size:letter portrait}body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}
</style></head><body>
<!-- La barra del visor. Va ANTES de la primera hoja y no al final del <body>, y no es cuestión
     de gusto: «.pg:last-child» es lo que le quita el «page-break-after:always» a la última hoja.
     Puesta al final, la última «.pg» deja de ser «:last-child», recupera el salto y TODO
     documento sale con una hoja de más en blanco. Es un elemento que solo existe en pantalla y
     aun así podía costar una hoja de papel por cotización. -->
<div class="visor">
  <span class="visor-t">Vista previa</span>
  <span class="visor-h">Hoja carta vertical &middot; ${TOTAL_HOJAS} ${TOTAL_HOJAS===1?'hoja':'hojas'}</span>
  <button class="visor-b" type="button" onclick="window.print()">Imprimir / Guardar PDF</button>
</div>
${marcaDef}

<!-- HOJAS DE COTIZACIÓN: una por cada trozo de filas, ya no se numeran fijo porque
     con muchas partidas son varias. Los totales y la nota cierran en la última; el pie
     va en todas, que era justo lo que se perdía cuando el bloque se pasaba de la hoja. -->
${trozos.map((trozo,ti)=>{
  const ultima = ti===trozos.length-1;
  const filas = trozo.map(filaHTML).join('');
  /* Lo que se cobra sin desglosar, para que la columna de totales cuadre con el subtotal. */
  const filaOculta = (ultima && Math.abs(subOculto)>0.01) ? `
      <tr class="${idxFila++%2===0?'re':'ro'}"><td><span class="cn">Conceptos adicionales</span></td><td class="c">—</td><td class="c">—</td><td class="r num">—</td><td class="r num tot">${money(subOculto)}</td></tr>` : '';
  /* La tabla ya no se rellena hasta cuatro filas. Con tres partidas quedaba una banda
     rayada vacía al final que se lee como un renglón que se perdió al imprimir. */
  return `
<div class="pg">
  ${deco}
  ${hdr('Cotización',Q.fecha)}
  ${fichaDatos()}
  <table>
    <thead><tr>
      <th style="width:40%">Descripción</th>
      <th class="c" style="width:15%">Medidas</th>
      <th class="c" style="width:8%">Pzas.</th>
      <th class="r" style="width:18%">Precio unitario</th>
      <th class="r" style="width:19%">Total</th>
    </tr></thead>
    <tbody>${filas}${filaOculta}</tbody>
  </table>
  ${ultima?`<div class="cierre">
    <div class="nota">
      <span class="lbl">Nota</span>
      <p>${esc(notaCliente())}</p>
      ${hayProrrateo?`<small>* Precio unitario prorrateado: el total de la partida es el que manda.</small>`:''}
    </div>
    <div class="tot-card">
      <div class="trow"><span>Subtotal</span><span>${money(subPdf)}</span></div>
      ${hayAjuste&&ajuste>0.01?`<div class="trow trow-ok"><span>Descuento</span><span>− ${money(descSinIva)}</span></div>`:''}
      ${hayAjuste&&ajuste<-0.01?`<div class="trow trow-av"><span>Ajuste</span><span>+ ${money(-descSinIva)}</span></div>`:''}
      ${hayAjuste?`<div class="trow"><span>Subtotal ${ajuste>0?'con descuento':'ajustado'}</span><span>${money(dFin.sub)}</span></div>`:''}
      ${Q.iva?`<div class="trow trow-iva"><span>I.V.A. 16%</span><span>${money(dFin.iva)}</span></div>`:''}
      <div class="neto"><span>${Q.iva?'Total neto':'Total'}</span><span>${money(dFin.neto)}</span></div>
      ${Q.anti>0?`<div class="pago">
        <span class="lbl">Plan de pago</span>
        <div class="trow" style="padding:3px 0"><span>Anticipo para arrancar</span><span>${money(Q.anti)}</span></div>
        <div class="trow" style="padding:3px 0"><span>Resta al entregar</span><span>${money(Math.max(0,dFin.neto-Q.anti))}</span></div>
      </div>`:''}
    </div>
  </div>
  ${figura()}`:`<div class="sigue">Las partidas continúan en la hoja siguiente. Los totales van al final.</div>`}
  ${footerCot(ti+1)}
</div>`;
}).join('')}

<!-- HOJA DE TÉRMINOS Y CONDICIONES · los ocho apartados, palabra por palabra.
     Antes eran ocho párrafos en negrita seguidos de sus viñetas, a 9.5 px, en dos columnas sin
     separación: una mancha de texto donde no se distinguía dónde acaba un apartado y empieza
     el siguiente. Ahora cada uno lleva su número en un cuadro azul y las dos columnas van
     partidas por una línea. El texto no cambió ni una palabra. -->
<div class="pg">
  ${deco}
  ${hdr('Términos y condiciones','')}
  <div class="tt">
    <div class="tt-col">${TERMINOS.slice(0,4).map((t,i)=>tsec(i+1,t)).join('')}</div>
    <div class="tt-div"></div>
    <div class="tt-col">${TERMINOS.slice(4).map((t,i)=>tsec(i+5,t)).join('')}</div>
  </div>
  <div class="acepta">
    <span class="lbl">Aceptación</span>
    <p>El depósito del anticipo implica la aceptación de estos términos (apartado 8). Si prefieres dejarla firmada, aquí:</p>
    <div class="acepta-f">
      <div>Nombre y firma del cliente</div>
      <div>Fecha</div>
    </div>
    <div class="acepta-m">${esc(Q.folio)}${Q.folio?' &nbsp;·&nbsp; ':''}${Q.iva?'Total neto':'Total'} ${money(dFin.neto)}</div>
  </div>
  ${footer([{label:'WhatsApp',val:esc(EMPRESA.whatsapp)},{label:'Dirección de la oficina',val:esc(EMPRESA.oficina)}],HOJA_TERMINOS)}
</div>

<!-- HOJAS DE ORDEN DE TRABAJO · la del taller, sin precios · solo si hay límite (hayLimite)
     La nota, el sello del límite y el plano cierran en la última, igual que los totales en la
     cotización: repetir el sello en cada hoja es la forma de que dos hojas de la misma orden
     digan fechas distintas cuando alguien corrige una y no la otra. -->
${trozosOT.map((trozo,ti)=>{
  const ultima = ti===trozosOT.length-1;
  return `
<div class="pg">
  ${deco}
  ${hdr('Orden de trabajo',Q.fecha)}
  ${fichaDatos()}
  <table>
    <thead><tr>
      <th style="width:58%">Descripción</th>
      <th class="c" style="width:26%">Medidas</th>
      <th class="c" style="width:16%">Pzas.</th>
    </tr></thead>
    <tbody>${trozo.map((it,i)=>`
      <tr class="${i%2===0?'re':'ro'}"><td>${desc(it)}</td><td class="c">${med(it)}</td><td class="c">${pzas(it)}</td></tr>`).join('')}</tbody>
  </table>
  ${ultima?`<div class="nota"><span class="lbl">Nota</span><p>${esc(notaCliente())}</p></div>
  <div class="sello"><div class="sello-in">
    <span class="lbl">Límite de fabricación</span>
    <div class="sello-f">${esc((Q.entrega||'').trim())}</div>
  </div></div>
  ${figura()}`:`<div class="sigue">Las partidas continúan en la hoja siguiente.</div>`}
  ${footerCot(HOJA_TRABAJO+ti)}
</div>`;}).join('')}

<!-- HOJA DE ORDEN DE INSTALACIÓN · solo si trae teléfono o entre calles (ver hayInstal)
     Lleva el plano: quien va a instalar necesita ver qué está instalando, y sin él la hoja
     eran dos datos arriba y tres cuartos de papel en blanco. Es la misma imagen del documento,
     no una nueva. hayInstal es un O, así que con solo uno de los dos datos la otra celda
     desaparece en vez de salir rotulada y vacía. -->
${hayInstal?`
<div class="pg">
  ${deco}
  ${hdr('Orden de instalación',Q.fecha)}
  ${fichaDatos()}
  <div class="datos">
    ${(Q.tel||'').trim()?`<div class="dato"><span class="lbl">Teléfono</span><span class="val">${esc(Q.tel)}</span></div>`:''}
    ${(Q.entrecalles||'').trim()?`<div class="dato"><span class="lbl">Entre calles</span><span class="val">${esc(Q.entrecalles)}</span></div>`:''}
  </div>
  <div class="nota"><span class="lbl">Nota</span><p>${esc(notaCliente())}</p></div>
  ${figura()}
  ${footerCot(HOJA_INSTAL)}
</div>`:''}

<!-- HOJA DE RECIBO DE PAGO · dos recibos con talón · solo si hay anticipo (hayRecibo) -->
${hayRecibo?(()=>{
  const cas = etq => `<span class="cas"><b></b>${etq}</span>`;
  const rl  = (etq,val) => `<div class="rline"><b>${etq}</b><span>${val||''}</span></div>`;
  const recibo = () => `
  <div class="rec">
    <div class="rec-tal">
      <div class="rec-logo">${logoH}</div>
      <span class="rec-badge">Talón — copia negocio</span>
      <div class="rec-tal-campos">
        <div class="rec-f"><span class="lbl">Fecha</span><div class="rec-l"></div></div>
        <div class="rec-f"><span class="lbl">Cliente</span><div class="rec-l">${esc(Q.cliente)}</div></div>
        <div class="rec-f"><span class="lbl">Monto $</span><div class="rec-l"></div></div>
      </div>
      <div class="pie-h">${Q.folio?esc(Q.folio)+' · ':''}Conserve este talón.</div>
    </div>
    <div class="rec-b">
      <div class="rec-h">
        <div style="display:flex;align-items:center;gap:10px">${logoH}<span class="rec-t">Recibo de pago</span></div>
        <div class="rec-fecha"><b>Fecha</b><i></i></div>
      </div>
      <div class="rule"></div><div class="rule2" style="margin-bottom:11px"></div>
      <div class="rec-campos">
        <div class="rline"><b>Concepto</b><span style="border:0;flex:0 0 auto;padding:0">${cas('Anticipo')}${cas('Liquidación')}</span></div>
        ${rl('Recibí de',esc(Q.cliente))}
        ${rl('La cantidad de $','')}
        ${rl('(con letra)','')}
        ${rl('Proyecto',esc(Q.proy))}
        <div class="rline"><b>Forma de pago</b><span style="border:0;flex:0 0 auto;padding:0">${cas('Efectivo')}${cas('Transferencia')}${cas('Tarjeta')}</span></div>
        ${rl('Saldo pendiente $','')}
      </div>
      <div class="rfirmas">
        <div class="rfirma">Entregué (cliente)</div>
        <div class="rfirma">Recibí — AL3D</div>
      </div>
      <div class="rpie">Este recibo no sustituye comprobante fiscal &nbsp;·&nbsp; Whatsapp ${esc(EMPRESA.whatsapp)}</div>
    </div>
  </div>`;
  return `
<div class="pg">
  ${recibo()}
  <div class="rcut"></div>
  ${recibo()}
  ${footer([{label:'Vendedor',val:esc(vendedorPdf)},{label:'WhatsApp',val:esc(EMPRESA.whatsapp)}],HOJA_RECIBO)}
</div>`;})():''}

</body></html>`;

  /* Ya no se auto-imprime. El documento se abría y a los 350 ms saltaba el diálogo de imprimir
     encima, así que la vista previa no se veía nunca: o se imprimía a ciegas, o se cancelaba y
     detrás quedaba una cinta blanca del ancho del navegador. Ahora la pestaña ES la vista
     previa —hojas carta verticales sobre fondo gris— y el diálogo lo abre la barra de arriba,
     cuando el que mira ya vio lo que va a mandar. */
  const printable = html;
  try{
    const blob = new Blob([printable], {type:'text/html'});
    const url = URL.createObjectURL(blob);
    const w = window.open(url, '_blank');
    if(w){
      setTimeout(()=>{ try{URL.revokeObjectURL(url);}catch(_){}}, 60000);
    }else{
      // Ventanas emergentes bloqueadas (muy común en móvil): ofrecemos un enlace real que el usuario toca.
      mostrarEnlacePDF(url);
    }
    /* El hito se pone aquí y no al entrar: si el navegador no dejó armar el documento, la
       entrega no avanzó y el renglón tiene que seguir diciendo «Generar PDF». El caso del
       emergente bloqueado sí cuenta: el enlace tocable ES el documento, ya armado. */
    marcarHito('pdf');
  }catch(e){
    // Respaldo final: método clásico por si el navegador no soporta Blob URLs.
    try{
      const w2 = window.open('','_blank');
      if(!w2){ toast('Permite ventanas emergentes para generar el PDF','err',3500); return; }
      w2.document.write(html); w2.document.close();
      /* Antes esto disparaba print() a los 700 ms por reloj, sin esperar a que las imágenes
         decodificaran: con un plano grande salía una hoja con el hueco en blanco. Ya no
         imprime solo —el documento trae su propia barra— así que solo se le da el foco. */
      w2.focus();
      marcarHito('pdf');
    }catch(_){ toast('Este navegador no permitió generar el PDF','err',3500); }
  }
}

/* Respaldo tocable: un <a> real siempre abre el PDF aunque window.open esté bloqueado en el celular */
function mostrarEnlacePDF(url){
  const prev=document.getElementById('pdf-fallback'); if(prev) prev.remove();
  const ov=document.createElement('div');
  ov.id='pdf-fallback';
  ov.style.cssText='position:fixed;inset:0;z-index:120;background:rgba(12,15,38,.7);display:flex;align-items:center;justify-content:center;padding:24px;backdrop-filter:blur(4px);-webkit-backdrop-filter:blur(4px)';
  ov.innerHTML='<div style="background:#fff;border-radius:18px;max-width:360px;width:100%;padding:24px;text-align:center;box-shadow:0 24px 80px rgba(0,0,0,.3)">'
    +'<div style="font-size:40px;margin-bottom:8px">'+ico('i-doc')+'</div>'
    +'<div style="font-size:15px;font-weight:800;color:var(--n9);margin-bottom:6px">Tu PDF está listo</div>'
    +'<div style="font-size:12.5px;color:var(--n6);margin-bottom:16px;line-height:1.5">Ábrelo y usa <b>Compartir → Imprimir / Guardar en PDF</b>.</div>'
    +'<a href="'+url+'" target="_blank" rel="noopener" onclick="cerrarEnlacePDF()" style="display:block;padding:14px;border-radius:11px;background:linear-gradient(135deg,var(--a),var(--a-claro));color:#fff;font-size:14px;font-weight:700;text-decoration:none;margin-bottom:9px">'+ico('i-doc')+' Abrir PDF</a>'
    +'<button onclick="cerrarEnlacePDF()" style="width:100%;padding:12px;border-radius:11px;background:#fff;border:1.5px solid var(--n3);color:var(--a);font-size:13px;font-weight:700;cursor:pointer;font-family:inherit">Cerrar</button>'
    +'</div>';
  ov.setAttribute('role','dialog');
  ov.setAttribute('aria-modal','true');
  ov.setAttribute('aria-label','Tu PDF está listo');
  ov.addEventListener('click',function(e){ if(e.target===ov) cerrarEnlacePDF(); });
  document.body.appendChild(ov);
  /* Se vigila igual que los otros siete, pero aquí hay que hacerlo al crearlo: el
     elemento no existe cuando corre _vigilarModales. La clase 'show' es la que dispara
     _modalAbierto —foco dentro, fondo inerte, foco guardado para la vuelta—. */
  ov.dataset.abierto='0';
  _obsModal.observe(ov,{attributes:true,attributeFilter:['class']});
  requestAnimationFrame(()=>ov.classList.add('show'));
}
/* Cerrar es quitar la clase y esperar: _modalCerrado devuelve el foco y despierta el
   fondo antes de que el nodo desaparezca. */
function cerrarEnlacePDF(){
  const ov=document.getElementById('pdf-fallback'); if(!ov) return;
  ov.classList.remove('show');
  requestAnimationFrame(()=>ov.remove());
}

